const items = [];

for (const item of $input.all()) {
  const output = item.json.stdout || '';

  // Parse download output
  const durationMatch = output.match(/DURATION:(\d+)/);
  const fileSizeMatch = output.match(/FILE_SIZE:(\S+)/);
  const resolutionMatch = output.match(/RESOLUTION:(\d+x\d+)/);
  const pathMatch = output.match(/PATH:(.+)/);

  const downloadedDuration = durationMatch ? parseInt(durationMatch[1]) : 60;
  const fileSize = fileSizeMatch ? fileSizeMatch[1] : 'unknown';
  const resolution = resolutionMatch ? resolutionMatch[1] : 'unknown';
  const downloadedPath = pathMatch ? pathMatch[1].trim() : '';

  // ✅ THE FIX: Grab the data strictly tied to the CURRENT loop item
  const node6Data = $('Split Posts').item.json;

  items.push({
    json: {
      // ✅ PASS ALL DATA FROM LOOP GATEKEEPER
      ...node6Data,

      // ✅ ADD DOWNLOAD INFO
      downloaded_path: downloadedPath,
      downloaded_duration: downloadedDuration,
      downloaded_file_size: fileSize,
      downloaded_resolution: resolution,
      work_dir: '/tmp/football_ai'
    }
  });
}

return items;

