const items = [];

// 1. ALL TARGET KEYWORDS
const targetKeywords = [
  'goal', 'goals', 'highlight', 'skill', 'assist',
  'save', 'miss', 'red card', 'penalty', 'free kick',
  'volley', 'bicycle', 'solo', 'banger', 'screamer',
  'tackle', 'amazing', 'insane', 'great'
];

// 2. ALL NEGATIVE KEYWORDS (Including the direct quote blocker '"')
const negativeKeywords = [
  'interview', 'interviewer', 'press conference', 'quotes', 
  'quote', 'speaks', 'says', 'podcast', 'statement', 'announced',
  '"', 'fabrizio', 'romano', 'ornstein', 'here we go', 'official',
  'news', 'rumour', 'agreed', 'signing', 'medical', 'contract'
];

// 3. FULL VIP WHITELIST
const allowedVideoSources = [
  'streamable', 'dubz', 'x.com', 'twitter.com', 'tiktok.com', 
  'facebook.com', 'youtube.com', 'youtu.be', 'instagram.com', 
  'fb.watch', 'v.redd.it'
];

for (const item of $input.all()) {
  const title = (item.json.title || '').toLowerCase();

  // RSS puts the Reddit post URL in 'link', and the HTML body in 'content'
  const postLink = (item.json.link || '').toLowerCase();
  const content = (item.json.content || '').toLowerCase();

  // THE INTERVIEW BOUNCER
  const isQuoteOrInterview = negativeKeywords.some(keyword => title.includes(keyword));
  if (isQuoteOrInterview) {
    continue;
  }

  // THE WHITELIST BOUNCER (Checks both the URL and the embedded content for VIP domains)
  const isWhitelisted = allowedVideoSources.some(source => postLink.includes(source) || content.includes(source));
  if (!isWhitelisted) {
    continue; 
  }

  // THE ACTION CHECK (Keywords OR the [1] - 0 bracket format)
  const hasKeyword = targetKeywords.some(keyword => title.includes(keyword));
  const hasGoalFormat = /\[\d+\]\s*-\s*\d+|\d+\s*-\s*\[\d+\]/.test(title);
  const isTargetContent = hasKeyword || hasGoalFormat;

  if (isTargetContent) {
    // Extract video ID safely from the Reddit URL
    const videoId = item.json.link.split('/comments/')[1]?.split('/')[0] || 'reddit_' + Math.random().toString(36).substring(7);

    items.push({
      json: {
        id: videoId,           
        video_id: videoId,
        title: item.json.title,
        reddit_url: item.json.link,
        video_url: item.json.link,   
        source_domain: "reddit",
        engagement_score: 2500, // Hardcoded fallback for AI processing
        upvotes: 1000,          // Hardcoded fallback for AI processing
        published_at: item.json.pubDate
      }
    });
  }
}

// Limit to top 3 to prevent server overload
return items.slice(0, 2);

const output = $input.first().json.stdout || '';

// Extract new IDs from output
const newIdsLine = output.match(/NEW_IDS:(.+)/);

if (!newIdsLine) {
  throw new Error('No new videos found - all already posted');
}

const newIds = newIdsLine[1].trim().split(' ').filter(Boolean);

console.log('New IDs found:', newIds);

// Get all items from Filter Football Posts node
const allItems = $('2. Filter Reddit RSS').all();

console.log('Total items from filter:', allItems.length);

// Filter to only new videos
const filteredItems = allItems.filter(item => 
  newIds.includes(item.json.id)
);

console.log('Filtered items:', filteredItems.length);

if (filteredItems.length === 0) {
  throw new Error('No new videos found after filtering');
}

return filteredItems;

// =============================================
// PARSE AI STRATEGIST OUTPUT (STRICT QUALITY CONTROL)
// Extracts, cleans, and validates all strategic decisions
// =============================================

const items = [];

for (const item of $input.all()) {
  try {
    // 1. Get the AI output text
    let responseText = item.json.output || '';

    // 2. Remove markdown code blocks if the AI accidentally adds them
    responseText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

    // 3. Parse the JSON
    const strategy = JSON.parse(responseText);

    // 4. VALIDATION: Ensure all critical fields exist (including youtube_seo)
    if (!strategy.content_type || !strategy.optimal_duration || !strategy.captions || !strategy.voiceover_script || !strategy.youtube_seo) {
      throw new Error('AI missing critical fields (Failed quality check)');
    }

    items.push({
      json: {
        // ✅ PRESERVE ORIGINAL VIDEO METADATA
        video_id: item.json.video_id || item.json.id,
        title: item.json.title,
        video_url: item.json.video_url,
        reddit_url: item.json.reddit_url,
        source_domain: item.json.source_domain,
        upvotes: item.json.upvotes,
        engagement_score: item.json.engagement_score,

        // ✅ STORE FULL STRATEGY (So YouTube SEO data passes downstream)
        strategy: strategy,

        // ✅ FLATTEN KEY FIELDS FOR EASY ACCESS
        duration: strategy.optimal_duration,
        risk_score: strategy.risk_score,
        risk_level: strategy.risk_level,
        caption_short: strategy.captions.short,

        // 👇 STRIP EMOJIS: Safe for FFmpeg burn-in so the video editor never crashes
        caption_video_safe: strategy.captions.short.replace(/[\p{Emoji_Presentation}\p{Extended_Pictographic}]/gu, '').replace(/\s+/g, ' ').trim(),

        caption_long: strategy.captions.long,
        voiceover_script: strategy.voiceover_script,

        // 👇 BULLETPROOF HASHTAGS: Safely handle arrays or strings without crashing
        hashtags: Array.isArray(strategy.hashtags) ? strategy.hashtags.join(' ') : strategy.hashtags || '#football #viral',

        use_backup_account: !strategy.posting_strategy?.primary_account,
        transformation_level: strategy.transformation_level || 'standard',
        start_offset: strategy.editing?.start_offset || 0
      }
    });

  } catch (error) {
    // 🗑️ FAIL-FAST: No fake fallbacks. If the AI messes up, log it and dump the video.
    console.error(`Skipping video ${item.json.video_id || item.json.id || 'unknown'} due to AI failure:`, error.message);
  }
}

// 🛑 SAFETY STOP: If all videos failed the AI check, halt the workflow.
if (items.length === 0) {
  throw new Error("All videos in this batch failed AI strategy parsing. Halting workflow to protect content quality.");
}

return items;
